function processYoutubers(inputString) {
    // Check if inputString is null, empty, or undefined
    const inputList = inputString ? inputString.split(',').map(item => item.trim()) : [];

    let result = [];
    for (let i = 1; i <= 5; i++) {
        let youtuber = {
            [`Youtuber ${i}`]: i <= inputList.length ? inputList[i-1] : `Youtuber ${i}`
        };
        result.push(youtuber);
    }
    return result;
}

// Example usage:
const inputString = $input.all()[0].json.youtubers;  // "item1,item2,item3"
const formattedList = processYoutubers(inputString);
return formattedList;

try {
    const input = $input.all()[0].json.youtubers;
    if (!input || input.trim() === '') {
        return [{"No Youtubers": true}];
    }
    const filteredYoutubers = input.split(',')
        .map(item => item.trim())
        .filter(item => item.startsWith('@'))
        .map(youtuber => ({
            youtuber: youtuber
        }));

    return filteredYoutubers.length > 0 ? filteredYoutubers : [{"No Youtubers": true}];
} catch (error) {
    return [{"No Youtubers": true}];
}

function decodeHtmlEntities(text) {
    if (!text) return '';

    return text
        .replace(/&amp;/g, '&')
        .replace(/&#39;/g, "'")
        .replace(/&quot;/g, '"')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&nbsp;/g, ' ');
}

const allItems = $input.all();
const result = [];

allItems.forEach(input => {
    if (input.json && input.json.items) {
        input.json.items.forEach(item => {
            if (item.id?.videoId && item.snippet?.title && item.snippet?.channelId) {
                result.push({
                    "channelId": item.snippet.channelId,
                    "videoId": item.id.videoId,
                    "title": decodeHtmlEntities(item.snippet.title)
                });
            }
        });
    }
});

return result;

const items = $input.all();
const processedItems = items.map(item => ({
    youtubeId: item.json.youtubeId,
    text: item.json.transcript.map(entry => 
        entry.text
            .replace(/&amp;/g, '&')
            .replace(/&#39;/g, "'")
            .replace(/&quot;/g, '"')
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&nbsp;/g, ' ')
    ).join(' ')
}));

return processedItems.map(item => ({
    json: item
}));

let items = $input.all()
    .filter(item => item.json.text)
    .map(item => ({
        "text": item.json.text.replace(/\[Music\]/g, '').trim()
    }));
return items;

