function generateYoutuberSections() {
    let photoIndex = findFirstIndexWithKey('output.photo');
    let videoIndex = findFirstIndexWithKey('videoId');
    let summaryIndex = findFirstIndexWithKey('output.summary');
    let transcriptIndex = findFirstIndexWithKey('text');
    let videoCounter = totalVideosPerYoutubers(videoIndex);

    const youtuberCount = countValidYoutubers();

    if (youtuberCount === 0) {
        return `<div class="no-youtubers-message">
            <p>No YouTubers found. Add your favorite YouTuber handles to receive personalized video summaries!</p>
        </div>`;
    }

    let completeSection = '';

    for (let i = 0; i < youtuberCount; i++) {
        // Create video cards dynamically
        let videoCards = '';
        for (let j = 0; j <= videoCounter; j++) {
            videoCards += `
                <div class="video-card">
                    <img src="https://i.ytimg.com/vi/${getNestedValue($input.all()[videoIndex + j]?.json, 'videoId') || 'missing'}/maxresdefault.jpg" 
                         onclick="window.location.href='https://www.youtube.com/watch?v=${getNestedValue($input.all()[videoIndex + j]?.json, 'videoId') || 'missing'}'" 
                         class="video-thumbnail" 
                         alt="Video Thumbnail">
                    <div class="video-info">
                        <div class="video-title">${getNestedValue($input.all()[videoIndex + j]?.json, 'title') || 'missing'}</div>
                        <div class="video-summary">${getNestedValue($input.all()[summaryIndex + j]?.json, 'output.summary') || 'missing'}</div>
                        <div class="transcript-container">
                            <div class="transcript-toggle" onclick="this.nextElementSibling.classList.toggle('active')">
                                Read Full Transcript
                            </div>
                            <div class="transcript-text">${getNestedValue($input.all()[transcriptIndex + j]?.json, 'text') || 'missing'}</div>
                        </div>
                    </div>
                </div>`;
        }

        const section = `
            <div class="youtuber-block">
                <div class="channel-header">
                    <img src="${getNestedValue($input.all()[photoIndex]?.json, 'output.photo') || 'missing'}" 
                         alt="Channel Thumbnail" 
                         class="channel-thumbnail">
                    <h2 class="youtuber-name">
                        <a href="https://www.youtube.com/${$input.all()[i+1].json['Youtuber ' + (i+1)]}" 
                           style="text-decoration: none; color: inherit;">
                            ${getNestedValue($input.all()[photoIndex]?.json, 'output.title') || 'missing'}
                        </a>
                    </h2>
                </div>
            </div>
            <div class="video-grid">
                ${videoCards}
            </div>`;

        completeSection += section;

        // Increment indices for next section
        photoIndex++;
        videoIndex += videoCounter + 1;
        summaryIndex += videoCounter + 1;
        transcriptIndex += videoCounter + 1;
    }

    return completeSection;
}

function totalVideosPerYoutubers() {
    let totalVideos = 0;
    // Count all videoIds in the input
    for (let i = 0; i < $input.all().length; i++) {
        if ($input.all()[i]?.json?.videoId) {
            totalVideos++;
        }
    }

    // Get total number of valid youtubers
    const validYoutubers = countValidYoutubers();

    // Calculate videos per youtuber (subtract 1 to exclude the first video)
    return (totalVideos / validYoutubers) - 1;
}

// Helper function to safely get nested values
function getNestedValue(obj, path) {
    if (!obj) return null;
    return path.split('.').reduce((current, key) => 
        (current && current[key] !== undefined) ? current[key] : null, obj);
}

// Rest of the helper functions remain the same
function findFirstIndexWithKey(keyPath) {
    const keys = keyPath.split('.');
    for (let i = 0; i < $input.all().length; i++) {
        let obj = $input.all()[i].json;
        let hasKey = true;
        for (const key of keys) {
            if (!obj || !obj.hasOwnProperty(key)) {
                hasKey = false;
                break;
            }
            obj = obj[key];
        }
        if (hasKey) return i;
    }
    return -1;
}

function countValidYoutubers() {
    let count = 0;
    for (let i = 1; i <= 5; i++) {
        const youtuberKey = `Youtuber ${i}`;
        const value = $input.all()[i]?.json[youtuberKey];
        if (value && value.includes('@')) {
            count++;
        }
    }
    return count;
}

function generateYoutuberInputs(count) {
    let result = '';

    for (let i = 1; i < count+1; i++) {
        const youtuberKey = `Youtuber ${i}`;
        const youtuberValue = $input.all()[i]?.json[youtuberKey];
        const value = youtuberValue?.includes('@') ? youtuberValue : '';

        const input = `<input type="text" class="youtuber-input" 
            value="${value}" 
            placeholder="YouTuber ${i}"
            oninput="document.getElementById('submitBtn').disabled = false">`;

        result += input + '\n';
    }

    return result;
}

